const raw = $input.first().json;
const item = raw && raw.body ? raw.body : raw;
const startedAt = new Date().toISOString();

if (!item.execution_id) throw new Error('Missing execution_id in payload');
if (!item.callback || !item.callback.url || !item.callback.secret) {
  throw new Error('Missing callback.url or callback.secret in payload');
}

const config = item.config || {};
const maxTickets = typeof config.max_tickets === 'number' ? Math.max(1, Math.min(100, config.max_tickets)) : 20;
const priorityThreshold = (config.priority_threshold || 'high').toString().toLowerCase();
const simulateFailure = config.simulate_failure === true;

const PRIORITY_RANK = { low: 1, medium: 2, high: 3, critical: 4 };
const thresholdRank = PRIORITY_RANK[priorityThreshold] || 3;

const buildCallback = (status, result, error, metrics) => {
  const finishedAt = new Date().toISOString();
  return {
    callbackUrl: item.callback.url,
    callbackSecret: item.callback.secret,
    callbackBody: {
      execution_id: item.execution_id,
      agent_instance_id: item.agent_instance_id,
      template_id: item.template_id,
      status,
      n8n_execution_id: $execution.id,
      started_at: startedAt,
      finished_at: finishedAt,
      metrics,
      result,
      error
    },
    httpResponse: { received: true, execution_id: item.execution_id, status }
  };
};

if (simulateFailure) {
  return [{
    json: buildCallback(
      'failed',
      null,
      { code: 'MOCK_PROVIDER_TIMEOUT', message: 'Simulated provider timeout for demo', retryable: true },
      { input_count: 0, output_count: 0, error_count: 1, tokens_input: 0, tokens_output: 0, estimated_cost_usd: 0 }
    )
  }];
}

const providedItems = item.input && Array.isArray(item.input.items) ? item.input.items : [];
const MOCK_TICKETS = [
  { ticket_id: 'TCK-001', subject: 'Urgent: billing charged twice this month', description: 'I was charged twice for my subscription. Please refund immediately, this is unacceptable.', customer_tier: 'pro' },
  { ticket_id: 'TCK-002', subject: 'Question about API rate limits',           description: 'Just a quick question on the documented API rate limits — does the limit reset per minute or per hour?', customer_tier: 'free' },
  { ticket_id: 'TCK-003', subject: 'Feature request: dark mode for exports',    description: 'Would love to see a dark mode option for the PDF exports. The current white background is hard on the eyes.', customer_tier: 'pro' },
  { ticket_id: 'TCK-004', subject: 'Slower login experience after the latest release', description: 'Since the latest release the login screen takes a few extra seconds to load. Not blocking, but worth flagging for the team.', customer_tier: 'enterprise' },
  { ticket_id: 'TCK-005', subject: 'Thanks for the great onboarding session',   description: 'Just wanted to say thanks for the helpful onboarding call yesterday. Everything is working great so far!', customer_tier: 'pro' }
];

const sourceTickets = providedItems.length > 0
  ? providedItems.map((t, idx) => ({
      ticket_id: t.ticket_id || ('TCK-' + String(idx + 1).padStart(3, '0')),
      subject: t.subject || '',
      description: t.description || '',
      customer_tier: t.customer_tier || 'free'
    }))
  : MOCK_TICKETS;
const tickets = sourceTickets.slice(0, maxTickets);

const HIGH_KEYWORDS = ['urgent', 'asap', 'immediately', 'crash', 'cannot login', "can't login", 'broken', 'down', 'outage', 'refund', 'unacceptable'];
const LOW_KEYWORDS = ['question', 'just wondering', 'how do i', 'thanks', 'thank you', 'appreciate'];
const BILLING_KEYWORDS = ['billing', 'charge', 'charged', 'invoice', 'refund', 'subscription', 'payment'];
const TECH_KEYWORDS = ['api', 'login', 'crash', 'error', 'bug', 'update', 'export', 'sso', 'integration'];
const FEATURE_KEYWORDS = ['feature request', 'would love', 'wish', 'could you add', 'suggest'];
const NEGATIVE_KEYWORDS = ['unacceptable', 'frustrating', 'angry', 'terrible', 'awful', 'cannot', "can't", 'broken', 'hate', 'worst', 'never works'];
const POSITIVE_KEYWORDS = ['thanks', 'thank you', 'great', 'love', 'awesome', 'helpful', 'amazing', 'appreciate'];

const lc = (s) => (s || '').toLowerCase();
const hasAny = (text, keywords) => keywords.some((kw) => text.includes(kw));

const classifyPriority = (text, tier) => {
  if (hasAny(text, HIGH_KEYWORDS) || (tier === 'enterprise' && hasAny(text, ['cannot', "can't", 'broken', 'down']))) return 'high';
  if (hasAny(text, LOW_KEYWORDS)) return 'low';
  return 'medium';
};

const classifyCategory = (text) => {
  if (hasAny(text, FEATURE_KEYWORDS)) return 'feature_request';
  if (hasAny(text, BILLING_KEYWORDS)) return 'billing_issue';
  if (hasAny(text, TECH_KEYWORDS)) return 'technical_support';
  return 'general_inquiry';
};

const classifySentiment = (text) => {
  const neg = hasAny(text, NEGATIVE_KEYWORDS);
  const pos = hasAny(text, POSITIVE_KEYWORDS);
  if (neg && !pos) return 'negative';
  if (pos && !neg) return 'positive';
  return 'neutral';
};

const triaged = tickets.map((t) => {
  const text = lc((t.subject || '') + ' ' + (t.description || ''));
  const priority = classifyPriority(text, t.customer_tier);
  const category = classifyCategory(text);
  const sentiment = classifySentiment(text);
  const rank = PRIORITY_RANK[priority] || 2;
  const assignedTeam = rank >= thresholdRank ? 'support_l2' : 'support_l1';
  return {
    ticket_id: t.ticket_id,
    priority,
    sentiment,
    category,
    assigned_team: assignedTeam
  };
});

const highCount = triaged.filter((x) => PRIORITY_RANK[x.priority] >= PRIORITY_RANK.high).length;
const summary = tickets.length + ' tickets triaged. ' + highCount + ' high-priority ticket' + (highCount === 1 ? '' : 's') + ' found.';

const tokensIn = tickets.reduce((sum, t) => sum + ((t.subject || '').length + (t.description || '').length), 0);
const tokensOut = JSON.stringify(triaged).length + summary.length;

return [{
  json: buildCallback(
    'success',
    {
      summary,
      data: {
        items_processed: tickets.length,
        tickets: triaged,
        summary
      }
    },
    null,
    {
      input_count: tickets.length,
      output_count: triaged.length,
      error_count: 0,
      tokens_input: Math.ceil(tokensIn / 4),
      tokens_output: Math.ceil(tokensOut / 4),
      estimated_cost_usd: Number((tickets.length * 0.0008).toFixed(4))
    }
  )
}];
